var coachLineupPriority='fit',coachLineupShape='',coachLineupReview=null,coachLineupNotice='',coachLineupCache=null;
function renderCoachLineup(){
 if(matchPopupActive!=='lineup'||view!=='match')return;const host=$('match-popup-lineup');if(!host)return;
 if(state!==season.match||typeof practiceSession!=='undefined'&&practiceSession){host.innerHTML='<p class="coach-lineup-note">전술 연습을 마친 뒤 실제 구단의 경기 준비에서 선발을 비교하세요.</p>';return;}
 const context=CoachLineup.key(season,customPositions)+'|'+coachLineupPriority;
 if(coachLineupCache?.key!==context){coachLineupCache={key:context,model:CoachLineup.read(season,coachLineupPriority,customPositions)};coachLineupReview=null;}
 const model=coachLineupCache.model;
 if(!model.canEdit){host.innerHTML='<p class="coach-lineup-note">다음 경기 준비에서 팀 대화 전에 코치와 선발을 비교하세요.</p>';return;}
 if(!model.options.some(p=>p.formation===coachLineupShape))coachLineupShape=model.recommended;
 const option=model.options.find(p=>p.formation===coachLineupShape),review=coachLineupReview,esc=escapeText;
 host.innerHTML='<section class="coach-lineup" aria-label="코치 선발 제안"><p class="eyebrow">선발을 정하는 세 가지 기준</p><h3>누구를 어디에 세울까요?</h3><div class="coach-lineup-filters"><label>선발 기준<select id="coach-lineup-priority">'+Object.entries(CoachLineup.priorities).map(([id,p])=>'<option value="'+id+'" '+(id===coachLineupPriority?'selected':'')+'>'+p.label+'</option>').join('')+'</select></label><label>포메이션<select id="coach-lineup-shape">'+model.options.map(p=>'<option value="'+p.formation+'" '+(p.formation===coachLineupShape?'selected':'')+'>'+p.formation.split('').join('-')+(p.formation===model.recommended?' · 코치 추천':'')+'</option>').join('')+'</select></label></div><p class="coach-lineup-note">'+esc(model.label)+' · 출전 가능한 선수로 각 자리를 비교합니다.</p><div class="coach-lineup-comparison"><div><small>배치 적합도 평균</small><b>'+model.before.fit+' → '+option.summary.fit+'</b></div><div><small>선발 체력 평균</small><b>'+model.before.energy+' → '+option.summary.energy+'</b></div></div>'+(review?'<p class="coach-lineup-review" role="status">선발 진입 '+review.entering.length+'명 · 제외 '+review.leaving.length+'명'+(review.resetsPositions?' · 수동 위치를 새 기본 배치로 정렬':'')+'</p>':'')+'<ul class="coach-lineup-eleven">'+option.players.map(p=>'<li>'+Portraits.html(p)+'<span class="coach-lineup-position">'+p.code+'</span><button type="button" class="coach-lineup-player" data-coach-player="'+esc(p.identity)+'">'+esc(p.name)+(state.lineup.includes(p.id)?'':'<small>새 선발</small>')+'</button><span class="coach-lineup-fit" title="배치 적합도 · 코치 평가">'+p.fit+'<small>'+(p.familiar?'익숙함':'적응 필요')+'</small></span><span class="coach-lineup-energy" role="img" aria-label="체력 '+p.energy+'" style="--energy:'+p.energy+'%;--energy-color:'+(p.energy>=70?'#8cdca3':p.energy>=40?'#efd46d':'#ef7c83')+'"><i></i></span></li>').join('')+'</ul><p class="coach-lineup-note">'+(option.summary.tired?'<strong>체력 주의 '+option.summary.tired+'명.</strong> ':'')+(option.summary.unfamiliar?'익숙하지 않은 배치 '+option.summary.unfamiliar+'곳. ':'')+esc(model.note)+'</p><div class="coach-lineup-actions">'+(review?'<button type="button" id="coach-lineup-apply" class="primary"'+(!review.changed?' disabled':'')+'>이 선발·포메이션 적용</button><button type="button" id="coach-lineup-cancel" class="secondary">비교로 돌아가기</button>':'<button type="button" id="coach-lineup-preview" class="primary">적용 전 변경 확인</button>')+'</div><p role="status" class="coach-lineup-note">'+esc(coachLineupNotice)+'</p></section>';
 $('coach-lineup-priority').onchange=event=>{coachLineupPriority=event.target.value;coachLineupShape='';coachLineupReview=null;coachLineupNotice='';renderCoachLineup();$('coach-lineup-priority')?.focus({preventScroll:true});};
 $('coach-lineup-shape').onchange=event=>{coachLineupShape=event.target.value;coachLineupReview=null;coachLineupNotice='';renderCoachLineup();$('coach-lineup-shape')?.focus({preventScroll:true});};
 host.querySelectorAll('[data-coach-player]').forEach(button=>button.onclick=()=>openPlayerDetails(button.dataset.coachPlayer,button));
 const preview=$('coach-lineup-preview');if(preview)preview.onclick=()=>{try{coachLineupReview=CoachLineup.preview(season,coachLineupShape,coachLineupPriority,customPositions);coachLineupNotice=coachLineupReview.changed?'11명과 배치 변경을 확인한 뒤 적용하세요.':'현재 선발과 같습니다.';}catch(error){coachLineupNotice=error.message;coachLineupReview=null;}renderCoachLineup();$('coach-lineup-apply')?.focus({preventScroll:true});};
 const cancel=$('coach-lineup-cancel');if(cancel)cancel.onclick=()=>{coachLineupReview=null;coachLineupNotice='비교를 취소했습니다. 기존 선발을 유지합니다.';renderCoachLineup();$('coach-lineup-preview')?.focus({preventScroll:true});};
 const apply=$('coach-lineup-apply');if(apply)apply.onclick=()=>{if(apply.disabled||!coachLineupReview)return;apply.disabled=true;try{if(state!==season.match||typeof practiceSession!=='undefined'&&practiceSession)throw Error('전술 연습을 마친 뒤 다시 비교하세요.');season=CoachLineup.apply(season,coachLineupShape,coachLineupPriority,coachLineupReview.fingerprint,customPositions);state=season.match;customPositions={};selected=null;rotationPreview=null;coachLineupReview=null;coachLineupCache=null;coachLineupNotice='선발을 적용했습니다. 전술 지시에서 세부 배치를 조정할 수 있어요.';save();render();if(!canSave){coachLineupNotice='선발은 적용됐지만 기기 저장에 실패했어요. 저장·복원에서 백업을 받아 주세요.';renderCoachLineup();}}catch(error){coachLineupReview=null;coachLineupNotice=error.message;renderCoachLineup();}$('coach-lineup-preview')?.focus({preventScroll:true});};
}
